<script module lang="ts">
/**
 * Vertical layout primitive (`design/components/stack.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/stack.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { type Snippet } from 'svelte'

import {
  attributes,
  joinSlot,
  spacingAttrs,
  type LayoutPatch,
  type SpaceStep,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/layout/layout.module.css'

export type StackAlign = NonNullable<StackProps['align']>

export type StackElement = NonNullable<StackProps['as']>

export type StackJustify = NonNullable<StackProps['justify']>

export interface StackProps {
  align?: 'stretch' | 'start' | 'center' | 'end'
  /**
   * List and form semantics without a wrapper element.
   */
  as?: 'form' | 'div' | 'section' | 'ul' | 'ol'
  children?: Snippet
  gap?: SpaceStep
  justify?: 'start' | 'center' | 'end' | 'between'
  p?: SpaceStep
  patch?: LayoutPatch
  px?: SpaceStep
  py?: SpaceStep
}
</script>

<script lang="ts">
let {
  align = 'stretch',
  as = 'div',
  children,
  gap,
  justify = 'start',
  p,
  patch,
  px,
  py,
}: StackProps = $props()
const joined = joinSlot(undefined, () => ({}))
</script>

{@render joined.start?.()
}{#if joined.shown
  }<svelte:element
    this={as}
    {...attributes(spacingAttrs({ gap, p, px, py, patch }))}
    class={[styles.layout, styles.stack]}
    data-align={align}
    data-justify={justify}
    data-member="stack"
    >{@render children?.()
  }</svelte:element
>{/if
}{@render joined.end?.()}
